 export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

+/** The trial at a horizon, or the lead trial when the feature has no such horizon. */
+export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
+	return h === "lead" ? leadTrial(f) : (f.trials.find((t) => t.h === h) ?? leadTrial(f));
+}
+
+/** Round axis ticks: a 1/2/5 step that yields about five intervals and always covers zero. */
+export function niceTicks(min: number, max: number): number[] {
+	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
+	let lo = Math.min(min, max, 0);
+	let hi = Math.max(min, max, 0);
+	if (lo === hi) return [lo];
+	const rough = (hi - lo) / 5;
+	const mag = 10 ** Math.floor(Math.log10(rough));
+	const norm = rough / mag;
+	const step = (norm <= 1.5 ? 1 : norm <= 3 ? 2 : norm <= 7 ? 5 : 10) * mag;
+	const first = Math.ceil(lo / step - 1e-9);
+	const last = Math.floor(hi / step + 1e-9);
+	const ticks: number[] = [];
+	for (let i = first; i <= last; i++) {
+		const v = i * step;
+		ticks.push(Math.abs(v) < step * 1e-9 ? 0 : Number(v.toPrecision(12)));
+	}
+	return ticks.includes(0) ? ticks : [...ticks, 0].sort((a, b) => a - b);
+}
+
+const pad2 = (n: number) => String(n).padStart(2, "0");
+
+/** UTC calendar label with dots, so "2022-01-01" cannot be mistaken for a January tick. */
+export function dateLabel(v: number | Date): string {
+	const d = v instanceof Date ? v : new Date(v);
+	return `${d.getUTCFullYear()}.${pad2(d.getUTCMonth() + 1)}.${pad2(d.getUTCDate())}`;
+}
+
+export interface ScreenCurveView {
+	t: number[];
+	rule: number[];
+	hold: number[];
+	ticks: number[];
+	labels: string[];
+}
+
+/** Percent-scaled curve for the chart; a missing point keeps the previous value. */
+export function curveView(trial: ScreenTrial | undefined | null): ScreenCurveView | null {
+	const curve = trial?.curve;
+	if (!curve || curve.t.length < 2) return null;
+	const carry = (xs: (number | null)[]): number[] => {
+		let last = 0;
+		return xs.map((x) => {
+			if (x != null && Number.isFinite(x)) last = x * 100;
+			return last;
+		});
+	};
+	const rule = carry(curve.rule);
+	const hold = carry(curve.hold);
+	const values = [...rule, ...hold].filter((v) => Number.isFinite(v));
